  1→using System.Text.Json;
  2→using DefaultEcs;
  3→using DefaultEcs.System;
  4→using Microsoft.Xna.Framework;
  5→using Microsoft.Xna.Framework.Content;
  6→using Microsoft.Xna.Framework.Graphics;
  7→using System;
  8→using System.Collections.Generic;
  9→using System.IO;
 10→using System.Linq;
 11→using MonoDreams.Component;
 12→using MonoDreams.Component.Collision;
 13→using MonoDreams.Component.Physics;
 14→using MonoDreams.Component.Draw;
 15→using MonoDreams.Level;
 16→using MonoDreams.Message.Level;
 17→using MonoDreams.Draw;
 18→using MonoDreams.Extension;
 19→using MonoDreams.State;
 20→using Logger = MonoDreams.State.Logger;
 21→
 22→namespace MonoDreams.System.Level;
 23→
 24→/// <summary>
 25→/// Parses Blender-exported JSON level files and creates entities for meshes.
 26→/// Handles LoadLevelRequest messages where the identifier starts with "Blender_".
 27→/// </summary>
 28→public sealed class BlenderLevelParserSystem : ISystem<GameState>
 29→{
 30→    private const float DEFAULT_LAYER_DEPTH = 0.5f;
 31→
 32→    private readonly World _world;
 33→    private readonly ContentManager _content;
 34→    private readonly MonoDreams.Component.Camera _camera;
 35→    private readonly Dictionary<string, Texture2D> _loadedTextures = new();
 36→    private readonly HashSet<Entity> _blenderEntities = new();
 37→    private readonly Dictionary<string, Entity> _nameToEntity = new();
 38→    private readonly Dictionary<string, Action<Entity, BlenderObject>> _collectionHandlers = new();
 39→    private DrawLayerMap _drawLayerMap;
 40→
 41→    public bool IsEnabled { get; set; } = true;
 42→
 43→    public BlenderLevelParserSystem(World world, ContentManager content, MonoDreams.Component.Camera camera)
 44→    {
 45→        _world = world ?? throw new ArgumentNullException(nameof(world));
 46→        _content = content ?? throw new ArgumentNullException(nameof(content));
 47→        _camera = camera ?? throw new ArgumentNullException(nameof(camera));
 48→
 49→        _world.Subscribe<LoadLevelRequest>(OnLoadLevelRequest);
 50→    }
 51→
 52→    /// <summary>
 53→    /// Registers a handler that will be called for entities belonging to the specified Blender collection.
 54→    /// This allows game code to add game-specific components to entities created by the core parser.
 55→    /// </summary>
 56→    public void RegisterCollectionHandler(string collectionName, Action<Entity, BlenderObject> handler)
 57→    {
 58→        _collectionHandlers[collectionName] = handler ?? throw new ArgumentNullException(nameof(handler));
 59→    }
 60→
 61→    /// <summary>
 62→    /// Sets the draw layer map used for depth resolution. When set, mesh depth is resolved by:
 63→    /// 1. Object's "drawLayer" custom property (string matching a layer name)
 64→    /// 2. Blender collection names matched against layer names
 65→    /// 3. Falls back to DEFAULT_LAYER_DEPTH
 66→    /// </summary>
 67→    public void SetDrawLayerMap(DrawLayerMap drawLayerMap)
 68→    {
 69→        _drawLayerMap = drawLayerMap ?? throw new ArgumentNullException(nameof(drawLayerMap));
 70→    }
 71→
 72→    [Subscribe]
 73→    private void OnLoadLevelRequest(in LoadLevelRequest request)
 74→    {
 75→        if (!IsEnabled) return;
 76→
 77→        // Only handle Blender levels
 78→        if (!request.LevelIdentifier.StartsWith("Blender_"))
 79→            return;
 80→
 81→        Logger.Info($"Loading Blender level: {request.LevelIdentifier}");
 82→
 83→        // Clean up previous entities
 84→        CleanupEntities();
 85→
 86→        try
 87→        {
 88→            // Load JSON file from Content directory
 89→            // The Content.RootDirectory gives us the path to the Content folder
 90→            var jsonPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, _content.RootDirectory, "blender_level.json");
 91→            Logger.Debug($"Loading Blender level from: {jsonPath}");
 92→            var jsonContent = File.ReadAllText(jsonPath);
 93→
 94→            var options = new JsonSerializerOptions
 95→            {
 96→                PropertyNameCaseInsensitive = true
 97→            };
 98→
 99→            var levelData = JsonSerializer.Deserialize<BlenderLevelData>(jsonContent, options);
100→
101→            if (levelData?.Objects == null)
102→            {
103→                Logger.Warning("No objects found in Blender level data.");
104→                return;
105→            }
106→
107→            Logger.Info($"Loaded {levelData.Objects.Count} objects from Blender level.");
108→
109→            // Pre-scan: identify collider children (names ending with "-collider" that have a parent)
110→            var colliderChildMap = new Dictionary<string, BlenderObject>();   // parent name → collider data
111→            var colliderChildNames = new HashSet<string>();
112→            foreach (var obj in levelData.Objects)
113→            {
114→                if (obj.Name.EndsWith("-collider") && !string.IsNullOrEmpty(obj.Parent))
115→                {
116→                    if (colliderChildMap.TryGetValue(obj.Parent, out var existing))
117→                    {
118→                        Logger.Warning($"Duplicate collider child for parent '{obj.Parent}': replacing '{existing.Name}' with '{obj.Name}'.");
119→                    }
120→                    colliderChildMap[obj.Parent] = obj;
121→                    colliderChildNames.Add(obj.Name);
122→                    Logger.Debug($"Found collider child '{obj.Name}' for parent '{obj.Parent}'.");
123→                }
124→            }
125→
126→            // Pass 1: Create all entities (skip collider children)
127→            foreach (var obj in levelData.Objects)
128→            {
129→                if (colliderChildNames.Contains(obj.Name))
130→                {
131→                    Logger.Debug($"Skipping collider child '{obj.Name}' (will be applied to parent).");
132→                    continue;
133→                }
134→
135→                switch (obj.Type)
136→                {
137→                    case "CAMERA":
138→                        ProcessCamera(obj, levelData.ScaleFactor);
139→                        break;
140→                    case "MESH":
141→                    case "GREASEPENCIL":
142→                        ProcessMesh(obj, levelData);
143→                        break;
144→                    case "EMPTY":
145→                        ProcessEmpty(obj);
146→                        break;
147→                    default:
148→                        Logger.Warning($"Skipping unknown object type: {obj.Type}");
149→                        break;
150→                }
151→            }
152→
153→            // Post-Pass 1: Apply collider children to parent entities
154→            foreach (var (parentName, colliderObj) in colliderChildMap)
155→            {
156→                ApplyColliderChild(parentName, colliderObj);
157→            }
158→
159→            // Pass 2: Set up parent-child relationships
160→            foreach (var obj in levelData.Objects)
161→            {
162→                if (string.IsNullOrEmpty(obj.Parent)) continue;
163→                if (colliderChildNames.Contains(obj.Name)) continue;
164→
165→                if (!_nameToEntity.TryGetValue(obj.Name, out var childEntity))
166→                {
167→                    Logger.Warning($"Parent linkage: child '{obj.Name}' not found in entity map.");
168→                    continue;
169→                }
170→                if (!_nameToEntity.TryGetValue(obj.Parent, out var parentEntity))
171→                {
172→                    Logger.Warning($"Parent linkage: parent '{obj.Parent}' not found for child '{obj.Name}'.");
173→                    continue;
174→                }
175→
176→                childEntity.SetParent(parentEntity);
177→                Logger.Debug($"Set parent of '{obj.Name}' to '{obj.Parent}'.");
178→            }
179→
180→            // Post-Pass 2: Propagate YSortOffset from parents to sprite children
181→            foreach (var obj in levelData.Objects)
182→            {
183→                if (string.IsNullOrEmpty(obj.Parent)) continue;
184→                if (colliderChildNames.Contains(obj.Name)) continue;
185→
186→                if (!_nameToEntity.TryGetValue(obj.Name, out var childEntity)) continue;
187→                if (!_nameToEntity.TryGetValue(obj.Parent, out var parentEntity)) continue;
188→
189→                if (childEntity.Has<SpriteInfo>() && parentEntity.Has<SpriteInfo>())
190→                {
191→                    ref readonly var parentSprite = ref parentEntity.Get<SpriteInfo>();
192→                    if (parentSprite.YSortOffset != 0f)
193→                    {
194→                        ref var childSprite = ref childEntity.Get<SpriteInfo>();
195→                        childSprite.YSortOffset = parentSprite.YSortOffset;
196→                        Logger.Debug($"Propagated YSortOffset={parentSprite.YSortOffset} from '{obj.Parent}' to '{obj.Name}'.");
197→                    }
198→                }
199→            }
200→
201→            Logger.Info($"Created {_blenderEntities.Count} entities from Blender level.");
202→        }
203→        catch (Exception ex)
204→        {
205→            Logger.Error($"Error loading Blender level: {ex.Message}\n{ex.StackTrace}");
206→        }
207→    }
208→
209→    private void ProcessCamera(BlenderObject cameraObj, float scaleFactor)
210→    {
211→        if (cameraObj.Position == null) return;
212→
213→        var cameraPosition = new Vector2(cameraObj.Position.X, cameraObj.Position.Y);
214→        _camera.Position = cameraPosition;
215→
216→        // Read ortho_scale from custom properties and convert to game zoom
217→        // Blender ortho_scale = visible width in Blender units
218→        // With scaleFactor, visible world pixels = ortho_scale * scaleFactor
219→        // Game zoom = virtualWidth / visible_world_pixels
220→        if (cameraObj.CustomProperties?.TryGetValue("zoom", out var zoomValue) == true)
221→        {
222→            if (zoomValue is JsonElement jsonElement && jsonElement.TryGetDouble(out var orthoScale))
223→            {
224→                // Convert Blender ortho_scale to game zoom
225→                var visibleWorldWidth = orthoScale * scaleFactor;
226→                var gameZoom = _camera.VirtualWidth / visibleWorldWidth;
227→                _camera.Zoom = (float)gameZoom;
228→                Logger.Debug($"Set camera zoom to {gameZoom} (from Blender ortho_scale {orthoScale}, scaleFactor {scaleFactor})");
229→            }
230→        }
231→
232→        Logger.Debug($"Set camera position to ({cameraPosition.X}, {cameraPosition.Y})");
233→    }
234→
235→    private void ProcessEmpty(BlenderObject emptyObj)
236→    {
237→        var entity = _world.CreateEntity();
238→        _blenderEntities.Add(entity);
239→
240→        var position = new Vector2(
241→            emptyObj.Position?.X ?? 0,
242→            emptyObj.Position?.Y ?? 0
243→        );
244→
245→        entity.Set(new Transform(position));
246→        entity.Set(new EntityInfo("Empty", emptyObj.Name));
247→
248→        _nameToEntity[emptyObj.Name] = entity;
249→
250→        // Invoke registered game-specific collection handlers
251→        if (emptyObj.Collections != null)
252→        {
253→            foreach (var collection in emptyObj.Collections)
254→            {
255→                if (_collectionHandlers.TryGetValue(collection, out var handler))
256→                {
257→                    handler(entity, emptyObj);
258→                }
259→            }
260→        }
261→
262→        Logger.Debug($"Created empty entity '{emptyObj.Name}' at ({position.X}, {position.Y})");
263→    }
264→
265→    private void ProcessMesh(BlenderObject meshObj, BlenderLevelData levelData)
266→    {
267→        if (meshObj.UvMapping == null)
268→        {
269→            Logger.Warning($"Skipping mesh '{meshObj.Name}' - no UV mapping.");
270→            return;
271→        }
272→
273→        // Extract content path from texture path
274→        var contentPath = ExtractContentPath(meshObj.UvMapping.TexturePath);
275→        if (string.IsNullOrEmpty(contentPath))
276→        {
277→            Logger.Warning($"Skipping mesh '{meshObj.Name}' - invalid texture path: {meshObj.UvMapping.TexturePath}");
278→            return;
279→        }
280→
281→        // Load texture
282→        Texture2D texture;
283→        if (!_loadedTextures.TryGetValue(contentPath, out texture))
284→        {
285→            try
286→            {
287→                texture = _content.Load<Texture2D>(contentPath);
288→                _loadedTextures[contentPath] = texture;
289→                Logger.Debug($"Loaded texture: {contentPath}");
290→            }
291→            catch (Exception ex)
292→            {
293→                Logger.Error($"Failed to load texture '{contentPath}': {ex.Message}");
294→                return;
295→            }
296→        }
297→
298→        // Get UV coordinates from first layer
299→        var uvLayer = meshObj.UvMapping.UvLayers?.FirstOrDefault();
300→        if (uvLayer?.UvCoordinates == null || uvLayer.UvCoordinates.Count == 0)
301→        {
302→            Logger.Warning($"Skipping mesh '{meshObj.Name}' - no UV coordinates.");
303→            return;
304→        }
305→
306→        // Calculate source rectangle from UV coordinates
307→        var sourceRect = CalculateSourceRect(uvLayer.UvCoordinates, texture);
308→
309→        // Create entity
310→        var entity = _world.CreateEntity();
311→        _blenderEntities.Add(entity);
312→        _nameToEntity[meshObj.Name] = entity;
313→
314→        // Position from Blender
315→        var position = new Vector2(
316→            meshObj.Position?.X ?? 0,
317→            meshObj.Position?.Y ?? 0
318→        );
319→
320→        // Transform
321→        entity.Set(new Transform(position));
322→
323→        // SpriteInfo with calculated source rectangle
324→        // Use mesh dimensions from Blender for Size (already scaled), fallback to source rect if not available
325→        var size = new Vector2(
326→            meshObj.Dimensions?.X ?? sourceRect.Width,
327→            meshObj.Dimensions?.Y ?? sourceRect.Height
328→        );
329→
330→        // Calculate origin from Blender's origin offset
331→        // Blender origin offset is normalized (0-1) where (0,0) is bottom-left and (0.5,0.5) is center
332→        // SpriteBatch.Draw expects origin in SOURCE TEXTURE coordinates (not destination size)
333→        var originOffsetX = meshObj.OriginOffset?.X ?? 0.5f;  // Default to center
334→        var originOffsetY = meshObj.OriginOffset?.Y ?? 0.5f;
335→        // Y is inverted: Blender Y=0 is bottom, engine Y=0 is top
336→        // Use sourceRect dimensions since SpriteBatch.Draw origin is in source coordinates
337→        var origin = new Vector2(sourceRect.Width * originOffsetX, sourceRect.Height * (1 - originOffsetY));
338→
339→        entity.Set(new SpriteInfo
340→        {
341→            SpriteSheet = texture,
342→            Source = sourceRect,
343→            Size = size,
344→            Color = Color.White,
345→            Target = RenderTargetID.Main,
346→            LayerDepth = ResolveLayerDepth(meshObj, levelData),
347→            Origin = origin
348→        });
349→
350→        // DrawComponent
351→        entity.Set(new DrawComponent
352→        {
353→            Type = DrawElementType.Sprite,
354→            Target = RenderTargetID.Main
355→        });
356→
357→        // Make visible
358→        entity.Set(new Visible());
359→
360→        // Process collection-based components
361→        ProcessCollections(entity, meshObj, size);
362→
363→        Logger.Debug($"Created entity for mesh '{meshObj.Name}' at ({position.X}, {position.Y}) with size ({size.X}, {size.Y}), origin ({origin.X}, {origin.Y}), and source rect ({sourceRect.X}, {sourceRect.Y}, {sourceRect.Width}, {sourceRect.Height})");
364→    }
365→
366→    /// <summary>
367→    /// Resolves the layer depth for a mesh object using the DrawLayerMap (if set).
368→    /// Priority: object "drawLayer" custom property > collection name match (with hierarchy walk) > DEFAULT_LAYER_DEPTH.
369→    /// </summary>
370→    private float ResolveLayerDepth(BlenderObject meshObj, BlenderLevelData levelData)
371→    {
372→        if (_drawLayerMap == null)
373→            return DEFAULT_LAYER_DEPTH;
374→
375→        // 1. Check object's "drawLayer" custom property
376→        if (meshObj.CustomProperties?.TryGetValue("drawLayer", out var drawLayerValue) == true)
377→        {
378→            var layerName = drawLayerValue is JsonElement jsonEl
379→                ? jsonEl.GetString()
380→                : drawLayerValue?.ToString();
381→
382→            if (layerName != null && _drawLayerMap.TryGetDepth(layerName, out var depth))
383→                return depth;
384→        }
385→
386→        // 2. Try each Blender collection name, then walk up the collection hierarchy
387→        if (meshObj.Collections != null)
388→        {
389→            foreach (var collection in meshObj.Collections)
390→            {
391→                var current = collection;
392→                while (current != null)
393→                {
394→                    if (_drawLayerMap.TryGetDepth(current, out var depth))
395→                        return depth;
396→
397→                    // Walk up the hierarchy if available
398→                    if (levelData.CollectionHierarchy == null ||
399→                        !levelData.CollectionHierarchy.TryGetValue(current, out current))
400→                        break;
401→                }
402→            }
403→        }
404→
405→        // 3. Fall back to default
406→        return DEFAULT_LAYER_DEPTH;
407→    }
408→
409→    /// <summary>
410→    /// Extracts the MonoGame Content path from a full file system path.
411→    /// Finds "/Content/" and returns the substring after it, without file extension.
412→    /// </summary>
413→    private static string ExtractContentPath(string fullPath)
414→    {
415→        if (string.IsNullOrEmpty(fullPath))
416→            return null;
417→
418→        var contentIndex = fullPath.IndexOf("/Content/", StringComparison.OrdinalIgnoreCase);
419→        if (contentIndex < 0)
420→        {
421→            // Try Windows-style path
422→            contentIndex = fullPath.IndexOf("\\Content\\", StringComparison.OrdinalIgnoreCase);
423→        }
424→
425→        if (contentIndex < 0)
426→            return null;
427→
428→        var separatorLength = "/Content/".Length;
429→        var relativePath = fullPath.Substring(contentIndex + separatorLength);
430→
431→        // Remove file extension
432→        var extensionIndex = relativePath.LastIndexOf('.');
433→        if (extensionIndex > 0)
434→        {
435→            relativePath = relativePath.Substring(0, extensionIndex);
436→        }
437→
438→        return relativePath;
439→    }
440→
441→    /// <summary>
442→    /// Calculates a source rectangle from UV coordinates.
443→    /// Assumes a plane mesh with 4 vertices.
444→    /// </summary>
445→    private static Rectangle CalculateSourceRect(List<UvCoordinate> uvCoords, Texture2D texture)
446→    {
447→        if (uvCoords == null || uvCoords.Count == 0)
448→            return Rectangle.Empty;
449→
450→        float minU = uvCoords.Min(uv => uv.U);
451→        float maxU = uvCoords.Max(uv => uv.U);
452→        float minV = uvCoords.Min(uv => uv.V);
453→        float maxV = uvCoords.Max(uv => uv.V);
454→
455→        // Convert UV to pixel coordinates with rounding for better precision
456→        // UV origin is bottom-left, texture origin is top-left, so flip V
457→        int x = (int)Math.Round(minU * texture.Width);
458→        int y = (int)Math.Round((1 - maxV) * texture.Height);
459→        int width = (int)Math.Round((maxU - minU) * texture.Width);
460→        int height = (int)Math.Round((maxV - minV) * texture.Height);
461→
462→        return new Rectangle(x, y, width, height);
463→    }
464→
465→    /// <summary>
466→    /// Processes Blender collection membership and adds appropriate components.
467→    /// Collection names determine entity behavior (e.g., "Collision" adds BoxCollider).
468→    /// Collection custom properties can configure component settings.
469→    /// </summary>
470→    private void ProcessCollections(Entity entity, BlenderObject meshObj, Vector2 size)
471→    {
472→        if (meshObj.Collections == null || meshObj.Collections.Count == 0)
473→            return;
474→
475→        // Compute visual offset from origin so collision boxes align with rendered sprites.
476→        // SpriteBatch.Draw renders at: position - origin * scale
477→        // In destination space: offset = -(size * originOffset)
478→        var originOffsetX = meshObj.OriginOffset?.X ?? 0.5f;
479→        var originOffsetY = meshObj.OriginOffset?.Y ?? 0.5f;
480→        // Compute float edges of visual bounds relative to entity position
481→        float left = -size.X * originOffsetX;
482→        float top = -size.Y * (1 - originOffsetY);  // Y inverted: Blender Y=0 is bottom
483→        // Snap to smallest enclosing integer rectangle (floor expands left/top, ceiling expands right/bottom)
484→        int intLeft = (int)Math.Floor(left);
485→        int intTop = (int)Math.Floor(top);
486→        int intRight = (int)Math.Ceiling(left + size.X);
487→        int intBottom = (int)Math.Ceiling(top + size.Y);
488→
489→        var boundsOffset = new Point(intLeft, intTop);
490→        var boundsSize = new Point(intRight - intLeft, intBottom - intTop);
491→
492→        // Check for Collision collection
493→        if (meshObj.Collections.Contains("Collision"))
494→        {
495→            entity.Set(new EntityInfo("Collision", meshObj.Name));
496→
497→            // Get collision layer from collection properties (default to -1 for all layers)
498→            int layer = -1;
499→            bool passive = false;
500→
501→            if (meshObj.CollectionProperties?.TryGetValue("Collision", out var collisionProps) == true)
502→            {
503→                layer = GetIntProperty(collisionProps, "layer", -1);
504→                passive = GetBoolProperty(collisionProps, "passive", false);
505→            }
506→
507→            var bounds = new Rectangle(boundsOffset, boundsSize);
508→            var activeLayers = new HashSet<int> { layer };
509→            entity.Set(new BoxCollider(bounds, activeLayers, passive));
510→
511→            Logger.Debug($"Added BoxCollider to '{meshObj.Name}' (layer: {layer}, passive: {passive})");
512→        }
513→
514→        // Check for Player collection — only root entities get physics/movement
515→        if (meshObj.Collections.Contains("Player"))
516→        {
517→            if (string.IsNullOrEmpty(meshObj.Parent))
518→            {
519→                entity.Set(new EntityInfo("Player", meshObj.Name));
520→                entity.Set(new BoxCollider(new Rectangle(boundsOffset, boundsSize)));
521→                entity.Set(new RigidBody());
522→                entity.Set(new Velocity());
523→
524→                entity.Set(new CameraFollowTarget
525→                {
526→                    DampingX = 5.0f,
527→                    DampingY = 5.0f,
528→                    MaxDistanceX = 150.0f,
529→                    MaxDistanceY = 100.0f,
530→                    IsActive = true
531→                });
532→                Logger.Debug($"Set Player for '{meshObj.Name}'");
533→            }
534→            else
535→            {
536→                Logger.Debug($"Skipping Player physics for child '{meshObj.Name}' (parent: '{meshObj.Parent}')");
537→            }
538→        }
539→
540→        // Check for Enemy collection
541→        if (meshObj.Collections.Contains("Enemy"))
542→        {
543→            entity.Set(new EntityInfo("Enemy", meshObj.Name));
544→            Logger.Debug($"Set Enemy for '{meshObj.Name}'");
545→        }
546→
547→        // Check for Trigger collection (collision but no physics push)
548→        if (meshObj.Collections.Contains("Trigger"))
549→        {
550→            if (!entity.Has<BoxCollider>())
551→            {
552→                var bounds = new Rectangle(boundsOffset, boundsSize);
553→                entity.Set(new BoxCollider(bounds, passive: true));
554→            }
555→            entity.Set(new EntityInfo("Trigger", meshObj.Name));
556→            Logger.Debug($"Set as Trigger zone for '{meshObj.Name}'");
557→        }
558→
559→        // Invoke registered game-specific collection handlers
560→        foreach (var collection in meshObj.Collections)
561→        {
562→            if (_collectionHandlers.TryGetValue(collection, out var handler))
563→            {
564→                handler(entity, meshObj);
565→            }
566→        }
567→    }
568→
569→    /// <summary>
570→    /// Applies a collider child's mesh vertices as a ConvexCollider on the parent entity.
571→    /// Replaces any existing BoxCollider (preserving its layer/passive settings).
572→    /// Sets YSortOffset on the parent's SpriteInfo and adds ColliderTag.
573→    /// </summary>
574→    private void ApplyColliderChild(string parentName, BlenderObject colliderObj)
575→    {
576→        if (!_nameToEntity.TryGetValue(parentName, out var parentEntity))
577→        {
578→            Logger.Warning($"Collider child '{colliderObj.Name}': parent entity '{parentName}' not found.");
579→            return;
580→        }
581→
582→        if (colliderObj.Vertices == null || colliderObj.Vertices.Count < 3)
583→        {
584→            Logger.Warning($"Collider child '{colliderObj.Name}': needs at least 3 vertices, got {colliderObj.Vertices?.Count ?? 0}.");
585→            return;
586→        }
587→
588→        // Build model vertices from exported data
589→        var modelVertices = new Vector2[colliderObj.Vertices.Count];
590→        for (var i = 0; i < colliderObj.Vertices.Count; i++)
591→        {
592→            modelVertices[i] = new Vector2(colliderObj.Vertices[i].X, colliderObj.Vertices[i].Y);
593→        }
594→
595→        // Offset model vertices to match sprite's visual position.
596→        // SpriteBatch.Draw renders at: position - origin * scale, shifting the visual.
597→        // BoxColliders account for this in ProcessCollections; ConvexColliders must too.
598→        if (parentEntity.Has<SpriteInfo>())
599→        {
600→            ref readonly var spriteInfo = ref parentEntity.Get<SpriteInfo>();
601→            var scaleX = spriteInfo.Source.Width > 0 ? spriteInfo.Size.X / spriteInfo.Source.Width : 1f;
602→            var scaleY = spriteInfo.Source.Height > 0 ? spriteInfo.Size.Y / spriteInfo.Source.Height : 1f;
603→            var offsetX = -spriteInfo.Origin.X * scaleX;
604→            var offsetY = -spriteInfo.Origin.Y * scaleY;
605→
606→            for (var i = 0; i < modelVertices.Length; i++)
607→            {
608→                modelVertices[i] = new Vector2(
609→                    modelVertices[i].X + offsetX,
610→                    modelVertices[i].Y + offsetY);
611→            }
612→        }
613→
614→        // Guard against degenerate shapes (e.g. all vertices collinear or on the same axis)
615→        float minX = float.MaxValue, maxX = float.MinValue;
616→        float minY = float.MaxValue, maxY = float.MinValue;
617→        foreach (var v in modelVertices)
618→        {
619→            if (v.X < minX) minX = v.X;
620→            if (v.X > maxX) maxX = v.X;
621→            if (v.Y < minY) minY = v.Y;
622→            if (v.Y > maxY) maxY = v.Y;
623→        }
624→        if (maxX - minX < 0.01f || maxY - minY < 0.01f)
625→        {
626→            Logger.Warning($"Collider child '{colliderObj.Name}': degenerate shape (width={maxX - minX}, height={maxY - minY}), skipping.");
627→            return;
628→        }
629→
630→        // Determine collision layer and passive flag
631→        HashSet<int> activeLayers = null;
632→        bool passive = false;
633→
634→        // If parent already has a BoxCollider (from ProcessCollections), inherit its settings and remove it
635→        if (parentEntity.Has<BoxCollider>())
636→        {
637→            ref readonly var existingBox = ref parentEntity.Get<BoxCollider>();
638→            activeLayers = existingBox.ActiveLayers;
639→            passive = existingBox.Passive;
640→            parentEntity.Remove<BoxCollider>();
641→            Logger.Debug($"Replaced BoxCollider on '{parentName}' with ConvexCollider from '{colliderObj.Name}'.");
642→        }
643→        else
644→        {
645→            // Check collider child's own collection properties for collision settings
646→            if (colliderObj.CollectionProperties != null)
647→            {
648→                foreach (var (_, props) in colliderObj.CollectionProperties)
649→                {
650→                    var layer = GetIntProperty(props, "layer", -1);
651→                    passive = GetBoolProperty(props, "passive", false);
652→                    activeLayers = new HashSet<int> { layer };
653→                    break;
654→                }
655→            }
656→        }
657→
658→        // Create ConvexCollider with rotation ignored (baked into model vertices)
659→        parentEntity.Set(new ConvexCollider(modelVertices, activeLayers, passive, ignoreTransformRotation: true));
660→
661→        // Set YSortOffset = max Y of model vertices (bottom of collider in Y-down coords)
662→        // maxY was already computed in the degenerate-shape guard above
663→        if (parentEntity.Has<SpriteInfo>())
664→        {
665→            ref var spriteInfo = ref parentEntity.Get<SpriteInfo>();
666→            spriteInfo.YSortOffset = maxY;
667→        }
668→
669→        Logger.Debug($"Applied ConvexCollider from '{colliderObj.Name}' to '{parentName}' ({modelVertices.Length} vertices, YSortOffset={maxY}).");
670→    }
671→
672→    /// <summary>
673→    /// Gets an integer property from collection properties dictionary.
674→    /// </summary>
675→    private static int GetIntProperty(Dictionary<string, object> props, string key, int defaultValue)
676→    {
677→        if (props == null || !props.TryGetValue(key, out var value))
678→            return defaultValue;
679→
680→        if (value is JsonElement jsonElement)
681→        {
682→            if (jsonElement.TryGetInt32(out var intVal))
683→                return intVal;
684→            if (jsonElement.TryGetDouble(out var doubleVal))
685→                return (int)doubleVal;
686→        }
687→
688→        if (value is int intValue)
689→            return intValue;
690→        if (value is double doubleValue)
691→            return (int)doubleValue;
692→        if (value is float floatValue)
693→            return (int)floatValue;
694→
695→        return defaultValue;
696→    }
697→
698→    /// <summary>
699→    /// Gets a boolean property from collection properties dictionary.
700→    /// </summary>
701→    private static bool GetBoolProperty(Dictionary<string, object> props, string key, bool defaultValue)
702→    {
703→        if (props == null || !props.TryGetValue(key, out var value))
704→            return defaultValue;
705→
706→        if (value is JsonElement jsonElement)
707→        {
708→            if (jsonElement.ValueKind == JsonValueKind.True)
709→                return true;
710→            if (jsonElement.ValueKind == JsonValueKind.False)
711→                return false;
712→        }
713→
714→        if (value is bool boolValue)
715→            return boolValue;
716→
717→        return defaultValue;
718→    }
719→
720→    private void CleanupEntities()
721→    {
722→        Logger.Info($"Cleaning up {_blenderEntities.Count} Blender entities...");
723→        foreach (var entity in _blenderEntities.ToArray())
724→        {
725→            if (entity.IsAlive)
726→            {
727→                entity.Dispose();
728→            }
729→        }
730→        _blenderEntities.Clear();
731→        _nameToEntity.Clear();
732→    }
733→
734→    public void Update(GameState state)
735→    {
736→        // Processing happens via message subscription
737→    }
738→
739→    public void Dispose()
740→    {
741→        CleanupEntities();
742→        _loadedTextures.Clear();
743→        GC.SuppressFinalize(this);
744→    }
745→}
